import re, time
from pathlib import Path
path=Path('[REDACTED LOCAL PATH]')
genes=[]
t=time.time()
with path.open() as f:
 for line in f:
  if line.startswith('#'): continue
  p=line.split('\\t')
  if len(p)<9: continue
  if p[2]=='gene':
   attrs=dict(re.findall(r'(\\S+?) \"(["'^"]*)"'"', p[8]))
   genes.append((p[0],int(p[3]),int(p[4]),p[6],attrs.get('gene_id',''),attrs.get('gene_name',''),attrs.get('gene_type','')))
print('genes',len(genes),'time',time.time()-t)
# save gene table in memory; inspect overlap for candidate chr9 and chr2
sj=[]
for line in Path('[REDACTED LOCAL PATH]').read_text().splitlines():
 p=line.split('\\t')
 if len(p)>=9 and p[5]=='0':
  sj.append((p[0],int(p[1]),int(p[2]),p[3],int(p[6]),int(p[7])))
# function overlap with gene interval
def overlap(j):
 c,s,e=strand,*_=j
 res=[]
 for g in genes:
  if g[0]==c and g[1]<=e and g[2]>=s and g[3]==strand:
   res.append(g)
 return res
for j in sj:
 if j[0]=='chr9' and 111660000<j[1]<111670000:
  print('chr9 SJ',j,'overlap',overlap(j))
for j in sj:
 if j[0]=='chr2' and 88800000<j[1]<90000000:
  print('chr2 SJ',j,'overlap',overlap(j))
PY"

